import { useUiStore } from '../store/ui';
import { ToastService, MessageService, ToastOptions, MessageOptions, DialogService, DialogOptions } from '@nhphero/vue-sapp/contracts';

export function createToastService(uiStore: ReturnType<typeof useUiStore>): ToastService {
  return {
    show: (options: ToastOptions) => uiStore.showToast(options),
    success: (title: string, description?: string, options: any = {}) => 
      uiStore.showToast({ id: options.id || title, message: description ? `${title}: ${description}` : title, type: 'success', ...options }),
    error: (title: string, description?: string, options: any = {}) => 
      uiStore.showToast({ id: options.id || title, message: description ? `${title}: ${description}` : title, type: 'error', ...options }),
    info: (title: string, description?: string, options: any = {}) => 
      uiStore.showToast({ id: options.id || title, message: description ? `${title}: ${description}` : title, type: 'info', ...options }),
    warning: (title: string, description?: string, options: any = {}) => 
      uiStore.showToast({ id: options.id || title, message: description ? `${title}: ${description}` : title, type: 'warning', ...options }),
  };
}

export function createMessageService(uiStore: ReturnType<typeof useUiStore>): MessageService {
  return {
    show: (options: MessageOptions) => uiStore.showMessage(options),
    confirm: (options: MessageOptions) => {
      return new Promise((resolve) => {
        uiStore.showMessage({
          ...options,
          type: 'confirm',
          onConfirm: () => {
            if (options.onConfirm) options.onConfirm();
            resolve(true);
          },
          onCancel: () => {
            if (options.onCancel) options.onCancel();
            resolve(false);
          }
        });
      });
    },
    prompt: (options: MessageOptions) => {
      return new Promise((resolve) => {
        uiStore.showMessage({
          ...options,
          type: 'prompt',
          onConfirm: (value) => {
            if (options.onConfirm) options.onConfirm(value);
            resolve(value);
          },
          onCancel: () => {
            if (options.onCancel) options.onCancel();
            resolve(null);
          }
        });
      });
    },
    success: (title: string, description?: string) => uiStore.showMessage({ title, description, type: 'success' }),
    error: (title: string, description?: string) => uiStore.showMessage({ title, description, type: 'error' }),
  };
}

export function createDialogService(uiStore: ReturnType<typeof useUiStore>): DialogService {
  return {
    open: (options: DialogOptions) => uiStore.openDialog(options),
    close: (id: string) => uiStore.closeDialog(id),
    closeAll: () => uiStore.closeAllDialogs(),
  };
}
